/**
 * Microsoft Outlook Node - Version 2
 * Discriminator: resource=messageAttachment, operation=download
 */


interface Credentials {
  microsoftOutlookOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Download an attachment from a message */
export type MicrosoftOutlookV2MessageAttachmentDownloadParams = {
  resource: 'messageAttachment';
  operation: 'download';
  authentication?: 'microsoftOutlookOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The mailbox the Service Principal should act on. In the action node this is evaluated per input item (an expression can target a different mailbox per item); the trigger resolves it once.
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"id","value":""}
 */
    mailbox?: { __rl: true; mode: 'id'; value: string; cachedResultName?: string };
/**
 * Message
 * @searchListMethod searchMessages
 * @default {"mode":"list","value":""}
 */
    messageId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Attachment
 * @searchListMethod searchAttachments
 * @default {"mode":"list","value":""}
 */
    attachmentId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Put Output in Field
 * @hint The name of the output field to put the binary file data in
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
};

export type MicrosoftOutlookV2MessageAttachmentDownloadOutput = {
  '@odata.mediaContentType'?: string;
  '@odata.type'?: string;
  contentType?: string;
  id?: string;
  isInline?: boolean;
  lastModifiedDateTime?: string;
  name?: string;
  size?: number;
};

export type MicrosoftOutlookV2MessageAttachmentDownloadNode = {
  type: 'n8n-nodes-base.microsoftOutlook';
  version: 2;
  config: NodeConfig<MicrosoftOutlookV2MessageAttachmentDownloadParams> & { credentials?: Credentials };
  output?: Items<MicrosoftOutlookV2MessageAttachmentDownloadOutput>;
};